        await spend(card.id, civilDate(2031, 10, 5), 1000, fun.id, { source: "RECURRING", externalId: `${netflix.id}:2031-10-05` });
        await spend(card.id, civilDate(2031, 10, 3), 4000, subscriptionsCategory.id);
